To read a QR code in Java, you can use the ZXing library, which is an open-source library for reading barcodes, including QR codes. Here's a simple example program that reads a QR code from an image file:

```
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;

import com.google.zxing.BinaryBitmap;
import com.google.zxing.LuminanceSource;
import com.google.zxing.MultiFormatReader;
import com.google.zxing.NotFoundException;
import com.google.zxing.RGBLuminanceSource;
import com.google.zxing.ReaderException;
import com.google.zxing.Result;
import com.google.zxing.common.HybridBinarizer;

public class QRCodeReader {
    public static void main(String[] args) throws IOException, NotFoundException {
        File qrCodeFile = new File("qrcode.png");
        java.awt.image.BufferedImage qrCodeImage = ImageIO.read(qrCodeFile);

        LuminanceSource source = new RGBLuminanceSource(qrCodeImage);
        BinaryBitmap bitmap = new BinaryBitmap(new HybridBinarizer(source));
        MultiFormatReader reader = new MultiFormatReader();

        try {
            Result result = reader.decode(bitmap);
            System.out.println("QR code content: " + result.getText());
        } catch (ReaderException e) {
            e.printStackTrace();
        }
    }
}
```

